insert into public.curriculum_objectives (year_group, subject, term, strand, objective, source, verbatim, checkpoint, sort_order) values
  (1, 'reading', 'all', 'Reading word reading', 'apply phonic knowledge and skills as the route to decode words', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 10),
  (1, 'reading', 'all', 'Reading word reading', 'respond speedily with the correct sound to graphemes (letters or groups of letters) for all 40+ phonemes, including, where applicable, alternative sounds for graphemes', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 20),
  (1, 'reading', 'all', 'Reading word reading', 'read accurately by blending sounds in unfamiliar words containing GPCs that have been taught', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 30),
  (1, 'reading', 'all', 'Reading word reading', 'read common exception words, noting unusual correspondences between spelling and sound and where these occur in the word', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 40),
  (1, 'reading', 'all', 'Reading word reading', 'read words containing taught GPCs and -s, -es, -ing, -ed, -er and -est endings', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 50),
  (1, 'reading', 'all', 'Reading word reading', 'read other words of more than one syllable that contain taught GPCs', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 60),
  (1, 'reading', 'all', 'Reading word reading', 'read words with contractions [for example, I''m, I''ll, we''ll], and understand that the apostrophe represents the omitted letter(s)', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 70),
  (1, 'reading', 'all', 'Reading word reading', 'read books aloud, accurately, that are consistent with their developing phonic knowledge and that do not require them to use other strategies to work out words', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 80),
  (1, 'reading', 'all', 'Reading word reading', 'reread these books to build up their fluency and confidence in word reading', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 90),
  (1, 'reading', 'all', 'Reading comprehension', 'develop pleasure in reading, motivation to read, vocabulary and understanding by: listening to and discussing a wide range of poems, stories and non-fiction at a level beyond that at which they can read independently' || chr(59) || ' being encouraged to link what they read or hear to their own experiences' || chr(59) || ' becoming very familiar with key stories, fairy stories and traditional tales, retelling them and considering their particular characteristics' || chr(59) || ' recognising and joining in with predictable phrases' || chr(59) || ' learning to appreciate rhymes and poems, and to recite some by heart' || chr(59) || ' discussing word meanings, linking new meanings to those already known', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 100),
  (1, 'reading', 'all', 'Reading comprehension', 'understand both the books they can already read accurately and fluently and those they listen to by: drawing on what they already know or on background information and vocabulary provided by the teacher' || chr(59) || ' checking that the text makes sense to them as they read, and correcting inaccurate reading' || chr(59) || ' discussing the significance of the title and events' || chr(59) || ' making inferences on the basis of what is being said and done' || chr(59) || ' predicting what might happen on the basis of what has been read so far', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 110),
  (1, 'reading', 'all', 'Reading comprehension', 'participate in discussion about what is read to them, taking turns and listening to what others say', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 120),
  (1, 'reading', 'all', 'Reading comprehension', 'explain clearly their understanding of what is read to them', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 130)
insert into public.curriculum_objectives (year_group, subject, term, strand, objective, source, verbatim, checkpoint, sort_order) values
  (1, 'english', 'all', 'Spoken language', 'listen and respond appropriately to adults and their peers', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 10),
  (1, 'english', 'all', 'Spoken language', 'ask relevant questions to extend their understanding and knowledge', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 20),
  (1, 'english', 'all', 'Spoken language', 'use relevant strategies to build their vocabulary', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 30),
  (1, 'english', 'all', 'Spoken language', 'articulate and justify answers, arguments and opinions', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 40),
  (1, 'english', 'all', 'Spoken language', 'give well-structured descriptions, explanations and narratives for different purposes, including for expressing feelings', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 50),
  (1, 'english', 'all', 'Spoken language', 'maintain attention and participate actively in collaborative conversations, staying on topic and initiating and responding to comments', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 60),
  (1, 'english', 'all', 'Spoken language', 'use spoken language to develop understanding through speculating, hypothesising, imagining and exploring ideas', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 70),
  (1, 'english', 'all', 'Spoken language', 'speak audibly and fluently with an increasing command of Standard English', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 80),
  (1, 'english', 'all', 'Spoken language', 'participate in discussions, presentations, performances, role play/improvisations and debates', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 90),
  (1, 'english', 'all', 'Spoken language', 'gain, maintain and monitor the interest of the listener(s)', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 100),
  (1, 'english', 'all', 'Spoken language', 'consider and evaluate different viewpoints, attending to and building on the contributions of others', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 110),
  (1, 'english', 'all', 'Spoken language', 'select and use appropriate registers for effective communication', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 120),
  (1, 'english', 'all', 'Writing transcription (spelling)', 'spell: words containing each of the 40+ phonemes already taught' || chr(59) || ' common exception words' || chr(59) || ' the days of the week', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 130),
  (1, 'english', 'all', 'Writing transcription (spelling)', 'name the letters of the alphabet: naming the letters of the alphabet in order' || chr(59) || ' using letter names to distinguish between alternative spellings of the same sound', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 140),
  (1, 'english', 'all', 'Writing transcription (spelling)', 'add prefixes and suffixes: using the spelling rule for adding -s or -es as the plural marker for nouns and the third person singular marker for verbs' || chr(59) || ' using the prefix un-' || chr(59) || ' using -ing, -ed, -er and -est where no change is needed in the spelling of root words [for example, helping, helped, helper, eating, quicker, quickest]', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 150),
  (1, 'english', 'all', 'Writing transcription (spelling)', 'apply simple spelling rules and guidance, as listed in English appendix 1', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 160),
  (1, 'english', 'all', 'Writing transcription (spelling)', 'write from memory simple sentences dictated by the teacher that include words using the GPCs and common exception words taught so far', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 170),
  (1, 'english', 'all', 'Writing transcription (handwriting)', 'sit correctly at a table, holding a pencil comfortably and correctly', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 180),
  (1, 'english', 'all', 'Writing transcription (handwriting)', 'begin to form lower-case letters in the correct direction, starting and finishing in the right place', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 190),
  (1, 'english', 'all', 'Writing transcription (handwriting)', 'form capital letters', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 200),
  (1, 'english', 'all', 'Writing transcription (handwriting)', 'form digits 0-9', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 210),
  (1, 'english', 'all', 'Writing transcription (handwriting)', 'understand which letters belong to which handwriting ''families'' (ie letters that are formed in similar ways) and to practise these', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 220),
  (1, 'english', 'all', 'Writing composition', 'write sentences by: saying out loud what they are going to write about' || chr(59) || ' composing a sentence orally before writing it' || chr(59) || ' sequencing sentences to form short narratives' || chr(59) || ' re-reading what they have written to check that it makes sense', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 230),
  (1, 'english', 'all', 'Writing composition', 'discuss what they have written with the teacher or other pupils', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 240),
  (1, 'english', 'all', 'Writing composition', 'read their writing aloud, clearly enough to be heard by their peers and the teacher', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 250),
  (1, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'develop their understanding of the concepts set out in English appendix 2 by: leaving spaces between words' || chr(59) || ' joining words and joining clauses using ''and''' || chr(59) || ' beginning to punctuate sentences using a capital letter and a full stop, question mark or exclamation mark' || chr(59) || ' using a capital letter for names of people, places, the days of the week, and the personal pronoun ''I''' || chr(59) || ' learning the grammar for year 1 in English appendix 2', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 260),
  (1, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'use the grammatical terminology in English appendix 2 in discussing their writing', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 1', true, null, 270)
insert into public.curriculum_objectives (year_group, subject, term, strand, objective, source, verbatim, checkpoint, sort_order) values
  (2, 'reading', 'all', 'Reading word reading', 'continue to apply phonic knowledge and skills as the route to decode words until automatic decoding has become embedded and reading is fluent', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 10),
  (2, 'reading', 'all', 'Reading word reading', 'read accurately by blending the sounds in words that contain the graphemes taught so far, especially recognising alternative sounds for graphemes', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 20),
  (2, 'reading', 'all', 'Reading word reading', 'read accurately words of two or more syllables that contain the same graphemes as above', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 30),
  (2, 'reading', 'all', 'Reading word reading', 'read words containing common suffixes', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 40),
  (2, 'reading', 'all', 'Reading word reading', 'read further common exception words, noting unusual correspondences between spelling and sound and where these occur in the word', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 50),
  (2, 'reading', 'all', 'Reading word reading', 'read most words quickly and accurately, without overt sounding and blending, when they have been frequently encountered', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 60),
  (2, 'reading', 'all', 'Reading word reading', 'read aloud books closely matched to their improving phonic knowledge, sounding out unfamiliar words accurately, automatically and without undue hesitation', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 70),
  (2, 'reading', 'all', 'Reading word reading', 'reread these books to build up their fluency and confidence in word reading', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 80),
  (2, 'reading', 'all', 'Reading comprehension', 'develop pleasure in reading, motivation to read, vocabulary and understanding by: listening to, discussing and expressing views about a wide range of contemporary and classic poetry, stories and non-fiction at a level beyond that at which they can read independently' || chr(59) || ' discussing the sequence of events in books and how items of information are related' || chr(59) || ' becoming increasingly familiar with and retelling a wider range of stories, fairy stories and traditional tales' || chr(59) || ' being introduced to non-fiction books that are structured in different ways' || chr(59) || ' recognising simple recurring literary language in stories and poetry' || chr(59) || ' discussing and clarifying the meanings of words, linking new meanings to known vocabulary' || chr(59) || ' discussing their favourite words and phrases' || chr(59) || ' continuing to build up a repertoire of poems learnt by heart, appreciating these and reciting some, with appropriate intonation to make the meaning clear', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 90),
  (2, 'reading', 'all', 'Reading comprehension', 'understand both the books that they can already read accurately and fluently and those that they listen to by: drawing on what they already know or on background information and vocabulary provided by the teacher' || chr(59) || ' checking that the text makes sense to them as they read, and correcting inaccurate reading' || chr(59) || ' making inferences on the basis of what is being said and done' || chr(59) || ' answering and asking questions' || chr(59) || ' predicting what might happen on the basis of what has been read so far', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 100),
  (2, 'reading', 'all', 'Reading comprehension', 'participate in discussion about books, poems and other works that are read to them and those that they can read for themselves, taking turns and listening to what others say', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 110),
  (2, 'reading', 'all', 'Reading comprehension', 'explain and discuss their understanding of books, poems and other material, both those that they listen to and those that they read for themselves', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 120)
