  (2, 'english', 'all', 'Spoken language', 'select and use appropriate registers for effective communication', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 120),
  (2, 'english', 'all', 'Writing transcription (spelling)', 'spell by: segmenting spoken words into phonemes and representing these by graphemes, spelling many correctly' || chr(59) || ' learning new ways of spelling phonemes for which 1 or more spellings are already known, and learn some words with each spelling, including a few common homophones' || chr(59) || ' learning to spell common exception words' || chr(59) || ' learning to spell more words with contracted forms' || chr(59) || ' learning the possessive apostrophe (singular) [for example, the girl''s book]' || chr(59) || ' distinguishing between homophones and near-homophones', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 130),
  (2, 'english', 'all', 'Writing transcription (spelling)', 'add suffixes to spell longer words including -ment, -ness, -ful, -less, -ly', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 140),
  (2, 'english', 'all', 'Writing transcription (spelling)', 'apply spelling rules and guidance, as listed in English appendix 1 (https://www.gov.uk', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 150),
  (2, 'english', 'all', 'Writing transcription (spelling)', 'write from memory simple sentences dictated by the teacher that include words using the GPCs, common exception words and punctuation taught so far', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 160),
  (2, 'english', 'all', 'Writing transcription (handwriting)', 'form lower-case letters of the correct size relative to one another', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 170),
  (2, 'english', 'all', 'Writing transcription (handwriting)', 'start using some of the diagonal and horizontal strokes needed to join letters and understand which letters, when adjacent to one another, are best left unjoined', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 180),
  (2, 'english', 'all', 'Writing transcription (handwriting)', 'write capital letters and digits of the correct size, orientation and relationship to one another and to lower-case letters', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 190),
  (2, 'english', 'all', 'Writing transcription (handwriting)', 'use spacing between words that reflects the size of the letters', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 200),
  (2, 'english', 'all', 'Writing composition', 'develop positive attitudes towards and stamina for writing by: writing narratives about personal experiences and those of others (real and fictional)' || chr(59) || ' writing about real events' || chr(59) || ' writing poetry' || chr(59) || ' writing for different purposes', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 210),
  (2, 'english', 'all', 'Writing composition', 'consider what they are going to write before beginning by: planning or saying out loud what they are going to write about' || chr(59) || ' writing down ideas and/or key words, including new vocabulary' || chr(59) || ' encapsulating what they want to say, sentence by sentence', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 220),
  (2, 'english', 'all', 'Writing composition', 'make simple additions, revisions and corrections to their own writing by: evaluating their writing with the teacher and other pupils' || chr(59) || ' rereading to check that their writing makes sense and that verbs to indicate time are used correctly and consistently, including verbs in the continuous form' || chr(59) || ' proofreading to check for errors in spelling, grammar and punctuation (for example, ends of sentences punctuated correctly)', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 230),
  (2, 'english', 'all', 'Writing composition', 'read aloud what they have written with appropriate intonation to make the meaning clear', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 240),
  (2, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'develop their understanding of the concepts set out in English appendix 2 by: learning how to use both familiar and new punctuation correctly - see English appendix 2 , including full stops, capital letters, exclamation marks, question marks, commas for lists and apostrophes for contracted forms and the possessive (singular)' || chr(59) || ' learn how to use: sentences with different forms: statement, question, exclamation, command' || chr(59) || ' expanded noun phrases to describe and specify [for example, the blue butterfly]' || chr(59) || ' the present and past tenses correctly and consistently, including the progressive form' || chr(59) || ' subordination (using when, if, that, or because) and co-ordination (using or, and, or but)' || chr(59) || ' the grammar for year 2 in English appendix 2' || chr(59) || ' some features of written Standard English', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 250),
  (2, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'use and understand the grammatical terminology in English appendix 2 in discussing their writing', 'National curriculum in England: English programmes of study, updated 16 July 2014, year 2', true, null, 260)
insert into public.curriculum_objectives (year_group, subject, term, strand, objective, source, verbatim, checkpoint, sort_order) values
  (3, 'reading', 'all', 'Reading word reading', 'apply their growing knowledge of root words, prefixes and suffixes (etymology and morphology) as listed in - see English appendix 1 , both to read aloud and to understand the meaning of new words they meet', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 10),
  (3, 'reading', 'all', 'Reading word reading', 'read further exception words, noting the unusual correspondences between spelling and sound, and where these occur in the word', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 20),
  (3, 'reading', 'all', 'Reading comprehension', 'develop positive attitudes to reading, and an understanding of what they read, by: listening to and discussing a wide range of fiction, poetry, plays, non-fiction and reference books or textbooks' || chr(59) || ' reading books that are structured in different ways and reading for a range of purposes' || chr(59) || ' using dictionaries to check the meaning of words that they have read' || chr(59) || ' increasing their familiarity with a wide range of books, including fairy stories, myths and legends, and retelling some of these orally' || chr(59) || ' identifying themes and conventions in a wide range of books' || chr(59) || ' preparing poems and play scripts to read aloud and to perform, showing understanding through intonation, tone, volume and action' || chr(59) || ' discussing words and phrases that capture the reader''s interest and imagination' || chr(59) || ' recognising some different forms of poetry [for example, free verse, narrative poetry]', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 30),
  (3, 'reading', 'all', 'Reading comprehension', 'understand what they read, in books they can read independently, by: checking that the text makes sense to them, discussing their understanding, and explaining the meaning of words in context' || chr(59) || ' asking questions to improve their understanding of a text' || chr(59) || ' drawing inferences such as inferring characters'' feelings, thoughts and motives from their actions, and justifying inferences with evidence' || chr(59) || ' predicting what might happen from details stated and implied' || chr(59) || ' identifying main ideas drawn from more than 1 paragraph and summarising these' || chr(59) || ' identifying how language, structure, and presentation contribute to meaning', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 40),
  (3, 'reading', 'all', 'Reading comprehension', 'retrieve and record information from non-fiction', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 50),
  (3, 'reading', 'all', 'Reading comprehension', 'participate in discussion about both books that are read to them and those they can read for themselves, taking turns and listening to what others say', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 3 and 4', true, null, 60)
