  (5, 'english', 'all', 'Spoken language', 'select and use appropriate registers for effective communication', 'National curriculum in England: English programmes of study, updated 16 July 2014, spoken language years 1 to 6', true, null, 120),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'use further prefixes and suffixes and understand the guidance for adding them', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 130),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'spell some words with ''silent'' letters [for example, knight, psalm, solemn]', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 140),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'continue to distinguish between homophones and other words which are often confused', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 150),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'use knowledge of morphology and etymology in spelling and understand that the spelling of some words needs to be learnt specifically, as listed in English appendix 1', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 160),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'use dictionaries to check the spelling and meaning of words', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 170),
  (5, 'english', 'all', 'Writing transcription (spelling)', 'use the first 3 or 4 letters of a word to check spelling, meaning or both of these in a dictionary', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 180),
