  (6, 'english', 'all', 'Writing transcription (handwriting and presentation)', 'write legibly, fluently and with increasing speed by: choosing which shape of a letter to use when given choices and deciding whether or not to join specific letters' || chr(59) || ' choosing the writing implement that is best suited for a task', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 200),
  (6, 'english', 'all', 'Writing composition', 'plan their writing by: identifying the audience for and purpose of the writing, selecting the appropriate form and using other similar writing as models for their own' || chr(59) || ' noting and developing initial ideas, drawing on reading and research where necessary' || chr(59) || ' in writing narratives, considering how authors have developed characters and settings in what pupils have read, listened to or seen performed', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 210),
  (6, 'english', 'all', 'Writing composition', 'draft and write by: selecting appropriate grammar and vocabulary, understanding how such choices can change and enhance meaning' || chr(59) || ' in narratives, describing settings, characters and atmosphere and integrating dialogue to convey character and advance the action' || chr(59) || ' précising longer passages' || chr(59) || ' using a wide range of devices to build cohesion within and across paragraphs' || chr(59) || ' using further organisational and presentational devices to structure text and to guide the reader [for example, headings, bullet points, underlining]', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 220),
  (6, 'english', 'all', 'Writing composition', 'evaluate and edit by: assessing the effectiveness of their own and others'' writing' || chr(59) || ' proposing changes to vocabulary, grammar and punctuation to enhance effects and clarify meaning' || chr(59) || ' ensuring the consistent and correct use of tense throughout a piece of writing' || chr(59) || ' ensuring correct subject and verb agreement when using singular and plural, distinguishing between the language of speech and writing and choosing the appropriate register', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 230),
  (6, 'english', 'all', 'Writing composition', 'proofread for spelling and punctuation errors', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 240),
