  (6, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'develop their understanding of the concepts set out in English appendix 2 by: recognising vocabulary and structures that are appropriate for formal speech and writing, including subjunctive forms' || chr(59) || ' using passive verbs to affect the presentation of information in a sentence' || chr(59) || ' using the perfect form of verbs to mark relationships of time and cause' || chr(59) || ' using expanded noun phrases to convey complicated information concisely' || chr(59) || ' using modal verbs or adverbs to indicate degrees of possibility' || chr(59) || ' using relative clauses beginning with who, which, where, when, whose, that or with an implied (ie omitted) relative pronoun' || chr(59) || ' learning the grammar for years 5 and 6 in English appendix 2', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 260),
  (6, 'english', 'all', 'Writing vocabulary grammar and punctuation', 'indicate grammatical and other features by: using commas to clarify meaning or avoid ambiguity in writing' || chr(59) || ' using hyphens to avoid ambiguity' || chr(59) || ' using brackets, dashes or commas to indicate parenthesis' || chr(59) || ' using semicolons, colons or dashes to mark boundaries between independent clauses' || chr(59) || ' using a colon to introduce a list' || chr(59) || ' punctuating bullet points consistently', 'National curriculum in England: English programmes of study, updated 16 July 2014, years 5 and 6', true, null, 270),
